package dev.gbppimentel.zzz;
import java.io.File;import java.nio.file.Files;import org.json.*;
public final class DailyTestBudgetTest{static int checks;static void check(boolean v){if(!v)throw new AssertionError("Test allowance "+checks);checks++;}public static void main(String[]args)throws Exception{File dir=Files.createTempDirectory("eridu-budget").toFile();try{check(DailyTestBudget.hold(dir,50,"production").isEmpty());DailyTestBudget.save(dir,new JSONObject().put("enabled",true).put("limit",120));String first=DailyTestBudget.hold(dir,40,"first");check(DailyTestBudget.used(DailyTestBudget.read(dir))==40);DailyTestBudget.confirm(dir,first);check(DailyTestBudget.used(DailyTestBudget.read(dir))==40);DailyTestBudget.hold(dir,80,"second");check(DailyTestBudget.used(DailyTestBudget.read(dir))==120);boolean denied=false;try{DailyTestBudget.hold(dir,1,"third");}catch(java.io.IOException e){denied=true;}check(denied);check(DailyTestBudget.read(dir).getJSONArray("transactions").length()==2);System.out.println(checks+" stored Battery allowance checks passed");}finally{for(File f:dir.listFiles())f.delete();dir.delete();}}}
